def requirements_report() -> tuple[bool, str]:
    ctx = {
        "park_active": True, "weather_active": True, "env_divergence_active": True,
        "real_form_active": True, "handedness_active": True, "starter_active": True,
        "bullpen_active": True, "sos_regression_active": True, "real_lines_only": True,
        "juice_cap_active": True, "window_integrity_active": True, "no_real_money": True,
    }
    return run_self_check(ctx)



def write_nrfi_board(games: list[dict], run_date: str) -> None:
    """Append the day's forced NRFI/YRFI calls to docs/nrfi_board.jsonl.

    Period runs only (PERIOD_ONLY=1): the 11 AM ET pull is the one canonical
    snapshot per slate — starters confirmed, markets posted. Deduped per
    (slate_date, game); a re-run never rewrites an existing call. This file
    is a CALIBRATION record; it never feeds the bet ledger.
    """
    import json as _json
    import os as _os
    if _os.environ.get("PERIOD_ONLY") != "1":
        return
    path = "docs/nrfi_board.jsonl"
    existing = set()
    try:
        with open(path) as f:
            for line in f:
                r = _json.loads(line)
                existing.add((r.get("slate_date"), r.get("game")))
    except FileNotFoundError:
        pass
    pulled_at = datetime.now(ET).isoformat()
    n = 0
    with open(path, "a") as f:
        for gm in games:
            board = gm.get("nrfi_board")
            game_str = f"{gm['away']} @ {gm['home']}"
            if board is None or (run_date, game_str) in existing:
                continue
            row = {"slate_date": run_date, "pulled_at": pulled_at,
                   "pull_tag": _os.environ.get("PULL_TAG") or "period",
                   "game": game_str, "graded": False, "result": None}
            row.update(board)
            f.write(_json.dumps(row) + "\n")
            n += 1
    print(f"NRFI/YRFI board: {n} forced calls written -> {path}")

def write_hr_board(games: list[dict], run_date: str, league) -> None:
    """Daily Top-10 HR probability board -> docs/hr_board.jsonl.

    Period runs only (one canonical late-morning snapshot). CALIBRATION
    record — batter props have no real lines on this odds tier, so these
    are never bets. Dedupe: one board per slate; re-runs never rewrite."""
    import json as _json
    import os as _os
    if _os.environ.get("PERIOD_ONLY") != "1":
        return
    path = "docs/hr_board.jsonl"
    try:
        with open(path) as f:
            for line in f:
                if _json.loads(line).get("slate_date") == run_date:
                    print("HR board: slate already written — skipping")
                    return
    except FileNotFoundError:
        pass
    if league is None:
        print("HR board: league unavailable — skipped")
        return
    from mlb_betting_model.v14 import hr_board as hrb
    rows = hrb.build_hr_board(league.client, games, league.client.season)
    if not rows:
        print("HR board: no batter data returned — nothing written")
        return
    pulled_at = datetime.now(ET).isoformat()
    with open(path, "a") as f:
        for i, r in enumerate(rows, 1):
            row = {"slate_date": run_date, "pulled_at": pulled_at, "rank": i,
                   "graded": False, "result": None}
            row.update(r)
            f.write(_json.dumps(row) + "\n")
    print(f"HR board: top {len(rows)} written -> {path}")


def write_props_board(games: list[dict], run_date: str, league) -> None:
    """Player-prop model-vs-market divergence -> docs/props_board.jsonl.

    Period runs only (one canonical snapshot). CALIBRATION RECORD, not
    bets: prop divergence at this stage is as likely to mean our model is
    worse than the market as it is to mean the market is wrong. Rows are
    graded nightly; promotion to locked picks waits on that record."""
    import json as _json
    import os as _os
    if _os.environ.get("PERIOD_ONLY") != "1":
        return
    if league is None:
        print("Props board: league unavailable — skipped")
        return
    path = "docs/props_board.jsonl"
    try:
        with open(path) as f:
            for line in f:
                if _json.loads(line).get("slate_date") == run_date:
                    print("Props board: slate already written — skipping")
                    return
    except FileNotFoundError:
        pass

    from mlb_betting_model.v14 import props as pr
    from mlb_betting_model.v14 import hr_board as hrb

    client = league.client
    # map "Away @ Home" -> odds-api event id (props are per-event only)
    event_ids = {}
    try:
        for ev in (client.worker.events() or []):
            a, h = ev.get("away_team"), ev.get("home_team")
            if a and h and ev.get("id"):
                event_ids[f"{a} @ {h}"] = ev["id"]
    except Exception as exc:
        print(f"Props board: event list unavailable ({exc}) — skipped")
        return
    if not event_ids:
        print("Props board: no events returned — skipped")
        return

    try:
        hr_probs = hrb.hr_probabilities(client, games, client.season)
    except Exception as exc:
        print(f"Props board: HR model unavailable ({exc})")
        hr_probs = {}

    try:
        bat_profiles = pr.build_batter_profiles(client, games, client.season)
    except Exception as exc:
        print(f"Props board: batter profiles unavailable ({exc})")
        bat_profiles = {}
    try:
        from mlb_betting_model.v14 import statcast as sc
        savant = sc.load_savant(client, client.season)
        print(f"Props board: Statcast loaded "
              f"({len(savant.get('pitchers') or {})} pitchers, "
              f"{len(savant.get('batters') or {})} batters)")
    except Exception as exc:
        print(f"Props board: Statcast unavailable ({exc}) — box-score rates only")
        savant = None
    rows = pr.build_props_board(client, games, client.season,
                                DEFAULT_BOOKMAKERS, hr_probs, event_ids,
                                bat_profiles=bat_profiles, savant=savant)
    if not rows:
        print("Props board: no two-sided prop markets returned — nothing written")
        return
    pulled_at = datetime.now(ET).isoformat()
    n_q = 0
    with open(path, "a") as f:
        for r in rows:
            row = {"slate_date": run_date, "pulled_at": pulled_at,
                   "pull_tag": _os.environ.get("PULL_TAG") or "period",
                   "graded": False, "result": None}
            row.update(r)
            f.write(_json.dumps(row) + "\n")
            n_q += 1 if r.get("qualified") else 0
    print(f"Props board: {len(rows)} prop divergences written "
          f"({n_q} clearing the {pr.EDGE_GATE:.0%} no-vig edge gate) -> {path}")


def lock_picks(games: list[dict], run_date: str) -> int:
    """Freeze every PLAY/LEAN with the LINE IT WAS TAKEN AT and a pull timestamp.

    This is what makes the midnight-line theory testable: picks and their lines
    are locked at pull time and appended to docs/locked_picks.jsonl, which is
    committed to the repo. They cannot be revised after results come in, so
    grading is honest. Each row also records the model total and home win prob
    so we can later compare the locked (midnight) line to the closing line.
    """
    import json as _json
    pulled_at = datetime.now(ET).isoformat()
    rows = []

    import os as _os
    PERIOD_MARKETS = ("F5 Total", "NRFI")
    period_only = _os.environ.get("PERIOD_ONLY") == "1"
    # Which pull is this? The 8am run takes the slate before the day's money
    # moves it; the 11am run re-prices with lineups. Dedupe (below) means the
    # 8am lock is never overwritten, so tagging lets us measure whether the
    # early price actually beat the later one.
    pull_tag = _os.environ.get("PULL_TAG") or "core"

    # Load rows already locked for this slate so a re-run never duplicates.
    already = set()
    try:
        with open("docs/locked_picks.jsonl") as _f:
            for _line in _f:
                _r = _json.loads(_line)
                if _r.get("slate_date") == run_date:
                    already.add((_r.get("model"), _r.get("game"),
                                 _r.get("market"), _r.get("pick")))
    except FileNotFoundError:
        pass

    def emit(gm, model_tag, verdicts_key, prices_key, hwp_key):
        for mkt, v in gm[verdicts_key].items():
            # Mode partition: midnight run -> core markets at the midnight
            # line; 15:00 UTC run -> period markets only (posted morning-of).
            if period_only != (mkt in PERIOD_MARKETS):
                continue
            if (model_tag, f"{gm['away']} @ {gm['home']}", mkt, v.pick) in already:
                continue
            if v.verdict in ("PLAY", "LEAN"):
                price_info = (gm.get(prices_key) or {}).get(mkt) or {}
                rows.append({
                    "pulled_at": pulled_at,
                    "slate_date": run_date,
                    "model": model_tag,                  # "A" (current) or "B" (variant)
                    "game": f"{gm['away']} @ {gm['home']}",
                    "market": mkt,
                    "pick": v.pick,
                    "verdict": v.verdict,
                    "score": v.score,
                    "pull_tag": pull_tag,
                    "line_at_pull": (gm.get("mkt_total") if mkt == "Total"
                                     else gm.get("mkt_f5_total") if mkt == "F5 Total"
                                     else 0.5 if mkt == "NRFI" else None),
                    "books": price_info.get("books", {}),
                    "best_book": price_info.get("best_book"),
                    "model_total": gm.get("model_total" if model_tag == "A" else "model_total_b"),
                    "home_win_prob": round(gm.get(hwp_key, 0.0), 4),
                    "env_note": gm.get("env_note", ""),
                    "close_book": None,    # filled by grade.py near gametime for CLV
                    "clv": None,           # filled by grade.py
                    "graded": False,
                    "result": None,
                })

    for gm in games:
        emit(gm, "A", "verdicts", "prices", "hwp")
        # MODEL B LOCKING RETIRED 2026-08-06. Delta backtest on the live
        # ledger: B-upgraded shared picks 23-24 (-3.07u) vs B-downgraded
        # 12-5 (+5.92u) — the xERA divergence signal scored BACKWARDS on
        # shared picks; verdict-crossing divergences went 3-6. Signal not
        # validated -> experiment retired, historical B rows preserved.
        # (B verdicts still render on the dashboard for reference.)
        # emit(gm, "B", "verdicts_b", "prices_b", "hwp_b")
    import os
    os.makedirs("docs", exist_ok=True)
    path = "docs/locked_picks.jsonl"
    with open(path, "a") as f:
        for r in rows:
            f.write(_json.dumps(r) + "\n")
    return len(rows)


def main():
    run_date = datetime.now(ET).strftime("%Y-%m-%d")
    ok, report = requirements_report()
    print(report)
    try:
        games = build_games(run_date)
    except Exception as exc:
        # FAIL LOUDLY (2026-08-09): a build failure previously produced a
        # GREEN run that overwrote the dashboard with an empty page and
        # silently skipped all locks and boards (observed 8/9 15:26 UTC —
        # transient upstream error, invisible until the diff was read).
        # Now: preserve yesterday's dashboard, write nothing, exit red.
        print(f"[fatal] build_games failed: {exc}", file=sys.stderr)
        import traceback
        traceback.print_exc()
        sys.exit(1)
    import os
    os.makedirs("docs", exist_ok=True)
    with open("docs/index.html", "w") as f:
        f.write(render_page(games, run_date))
    n_locked = lock_picks(games, run_date)
    write_nrfi_board(games, run_date)
    write_hr_board(games, run_date, globals().get("_LEAGUE_REF"))
    write_props_board(games, run_date, globals().get("_LEAGUE_REF"))
    print(f"Wrote docs/index.html for {run_date} ({len(games)} games)")
    print(f"Locked {n_locked} picks at the midnight line -> docs/locked_picks.jsonl")


if __name__ == "__main__":
    main()
